const std = @import("std"); const inde = @import("st-page-inde.zig"); const stor = @import("st-carz-stor.zig"); const typz = @import("pa-carz-type.zig"); const snap = @import("sy-carz-snap.zig"); const cmok = @import("sy-clou-mock.zig"); const file = @import("st-stor-file.zig");
const NOWZ: i64 = 1_795_600_000_000;
fn mkzz(urlz: []const u8, pric: i64) typz.Carz { return .{ .urlz = urlz, .site = "x.vn", .lidz = "1", .make = "Toyota", .modl = "Fortuner", .year = 2017, .cond = "used", .kmzz = 84281, .pric = pric, .prov = "Bình Dương", .phon = "0966353678", .text = "mô tả \"quoted\" và xuống\ndòng" }; }
test "snapshot: three objects, phone hash yes raw phone no, second run sends nothing, a change sends again" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 500_000_000), "h1", NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-2", 400_000_000), "h2", NOWZ); var cldz = cmok.Mock.init(allo); defer cldz.deinit(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const sto1 = cldz.store();
    const rsl1 = try snap.snapRunz(&dbzz, sto1, std.testing.io, aren.allocator()); try std.testing.expectEqual(@as(u8, 2), rsl1.sent); try std.testing.expectEqual(@as(u8, 1), rsl1.same); try std.testing.expectEqual(@as(usize, 2), cldz.map.count()); const gzzz = cldz.map.get(snap.KEYS[0]).?; const rawz = try file.gzipOpen(aren.allocator(), gzzz, 1 << 20); try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, rawz, "\n")); try std.testing.expect(std.mem.indexOf(u8, rawz, "0966353678") == null); try std.testing.expect(std.mem.indexOf(u8, rawz, "\"phsh\":\"") != null); try std.testing.expect(std.mem.indexOf(u8, rawz, "\\\"quoted\\\"") != null);
    const rsl2 = try snap.snapRunz(&dbzz, sto1, std.testing.io, aren.allocator()); try std.testing.expectEqual(@as(u8, 0), rsl2.sent); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 450_000_000), "h3", NOWZ + 1000); const rsl3 = try snap.snapRunz(&dbzz, sto1, std.testing.io, aren.allocator()); try std.testing.expectEqual(@as(u8, 2), rsl3.sent); }
test "snapshot: a store that keeps nothing fails loudly and leaves the flag alone" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); _ = try stor.carzSave(&stoz, mkzz("https://x.vn/a-1", 500_000_000), "h1", NOWZ); var cldz = cmok.Mock.init(allo); defer cldz.deinit(); cldz.stoo = true; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expect(std.meta.isError(snap.snapRunz(&dbzz, cldz.store(), std.testing.io, aren.allocator()))); cldz.stoo = false; const rsl2 = try snap.snapRunz(&dbzz, cldz.store(), std.testing.io, aren.allocator()); try std.testing.expectEqual(@as(u8, 2), rsl2.sent); }
